export default function ComingSoonCards({ singleCard = null }) {
  const showAds = !singleCard || singleCard === "advertisements";
  const showStaff = !singleCard || singleCard === "staff-management";

  return (
    <div style={{ margin: "10px", }}>
      <div style={{
        display: "grid",
        gridTemplateColumns: showAds && showStaff ? "repeat(auto-fit, minmax(320px, 1fr))" : "minmax(320px, 480px)",
        gap: "32px",
        justifyContent: "center"
      }}>

        {/* Advertisements Card */}
        {showAds && (
          <div style={cardStyle}>
            <div style={illustrationWrap}>
              <AdIllustration />
            </div>
            <p style={descStyle}>
              Showcase your business, offers, and services to thousands of pet owners.
            </p>
            <div style={{ display: "flex", justifyContent: "center" }}>
              <button style={btnStyle} disabled>
                <ClockIcon />
                <span>Coming Soon</span>
              </button>
            </div>
          </div>
        )}

        {/* Staff Management Card */}
        {showStaff && (
          <div style={cardStyle}>
            <div style={illustrationWrap}>
              <StaffIllustration />
            </div>
            <p style={descStyle}>
              Easily add staff members, assign permissions, and track their responsibilities
            </p>
            <div style={{ display: "flex", justifyContent: "center" }}>
              <button style={btnStyle} disabled>
                <ClockIcon />
                <span>Coming Soon</span>
              </button>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

/* ── Component Styles ── */
const cardStyle = {
  background: "#ffffff",
  borderRadius: "16px",
  padding: "24px",
  boxShadow: "0 4px 20px rgba(0, 0, 0, 0.04)",
  border: "1px solid #f1f5f9",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  textAlign: "center",
  transition: "transform 0.2s ease, box-shadow 0.2s ease",
};

const illustrationWrap = {
  width: "100%",
  display: "flex",
  justifyContent: "center",
  marginBottom: "20px",
  overflow: "hidden",
  borderRadius: "16px",
};

const descStyle = {
  fontSize: "14px",
  color: "#334155",
  lineHeight: 1.5,
  fontWeight: "500",
  marginBottom: "24px",
  minHeight: "42px",
  maxWidth: "340px",
};

const btnStyle = {
  background: "#1d6bf3",
  color: "#ffffff",
  border: "none",
  borderRadius: "6px",
  padding: "10px 24px",
  fontSize: "13px",
  fontWeight: "600",
  display: "inline-flex",
  alignItems: "center",
  gap: "8px",
  cursor: "default",
  boxShadow: "0 2px 8px rgba(29, 107, 243, 0.25)",
};
